["from verl.experimental.agent_loop.envs.asb_envs.BaseEnv import BaseEnv

class InventoryManagement_8(BaseEnv):
    def __init__(self, *, parameters=None):
        super().__init__()
        self.parameters = parameters if parameters is not None else {}
        self.inventory = self.parameters.get("inventory", [])

    def list_inventory(self):
        return {"success": True, "data": {"inventory": self.inventory}}

    def update_inventory(self, *, product_id, quantity):
        for item in self.inventory:
            if item.get("product_id") == product_id:
                item["quantity"] = quantity
                return {"success": True}
        return {"success": False, "message": "Product not found."}

    def flag_low_stock(self, *, product_id, threshold):
        for item in self.inventory:
            if item.get("product_id") == product_id and item.get("quantity", 0) < threshold:
                return {"success": True, "message": "Low stock flagged."}
        return {"success": False, "message": "Stock level adequate."}
