class DeliverySchedule(BaseEnv):
    def __init__(self, *, parameters=None):
        super().__init__()
        self.parameters = parameters if parameters is not None else {}
        self.schedules = self.parameters.get("schedules", [])

    def list_schedules(self):
        return {"success": True, "data": {"schedules": self.schedules}}

    def update_delivery_schedule(self, *, order_id, new_date):
        for schedule in self.schedules:
            if schedule.get("order_id") == order_id:
                schedule["delivery_date"] = new_date
                return {"success": True}
        return {"success": False, "message": "Schedule not found for order."}

    def flag_delivery_delay(self, *, order_id, reason):
        return {"success": True, "message": "Delay flagged for order: " + order_id + ", reason: " + reason}
